import{_ as s,a0 as i,w as l,s as u,ao as d,I as o,x as a,a1 as e,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"10個有用的Linux命令面試問題及答案 | LCTT x X-CMD","titleTemplate":false,"description":"10個有用的Linux命令面試問題及答案 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10個有用的Linux命令面試問題及答案 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10個有用的Linux命令面試問題及答案 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140722 10 Useful Interview Questions and Answers on Linux Commands","title":"10個有用的Linux命令面試問題及答案","tag":"201408","desc":""},"relativePath":"201408/20140722 10 Useful Interview Questions and Answers on Linux Commands.md","filePath":"[post].md"}'),p={name:"201408/20140722 10 Useful Interview Questions and Answers on Linux Commands.md"};function m(x,n,h,f,L,g){const t=i("Link");return l(),u("div",null,[n[13]||(n[13]=d(`<h1 id="_10個有用的linux命令面試問題及答案" tabindex="-1">10個有用的Linux命令面試問題及答案 <a class="header-anchor" href="#_10個有用的linux命令面試問題及答案" aria-label="Permalink to “10個有用的Linux命令面試問題及答案”">​</a></h1><p>Linux命令列，以及用户使用Linux命令進行Linux shell交互，是Linux最吸引人的地方，也是面試中最普遍的話題之一。在這篇文章中，我們將提出10個面試中很重要問題，這肯定能拓寬你的知識面。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Linux-Command-Questions.png" alt="Linux Command Questions"> Linux Command Questions</p><h3 id="_1-如何暫停一個正在運行的進程-讓其在後台運行" tabindex="-1">1. 如何暫停一個正在運行的進程，讓其在後台運行？ <a class="header-anchor" href="#_1-如何暫停一個正在運行的進程-讓其在後台運行" aria-label="Permalink to “1. 如何暫停一個正在運行的進程，讓其在後台運行？”">​</a></h3><p><strong>答案</strong>：為了停止正在運行的進程，讓其在後台運行，我們可以使用組合鍵 Ctrl+Z。</p><h3 id="_2-什麼是安裝linux所需的最小分區數量-以及如何查看系統啓動信息" tabindex="-1">2. 什麼是安裝Linux所需的最小分區數量，以及如何查看系統啓動信息？ <a class="header-anchor" href="#_2-什麼是安裝linux所需的最小分區數量-以及如何查看系統啓動信息" aria-label="Permalink to “2. 什麼是安裝Linux所需的最小分區數量，以及如何查看系統啓動信息？”">​</a></h3><p><strong>答案</strong>：單獨一個/root分區足以執行所有的系統任務，但是強烈建議安裝Linux時，需要至少三個分區：/root,/boot,/swap。一個IDE硬盤驅動器支持高達63個分區，SCSI硬盤驅動器支持超過15個分區。</p><p>為了檢查啓動信息，我們可以使用cat或者dmesg命令，如下所示：</p><pre><code>#cat /var/log/messages
</code></pre><p>OR</p><pre><code>#dmesg
</code></pre><h3 id="_3-在你的linux機器上跟蹤系統事件的守護進程名是什麼" tabindex="-1">3. 在你的Linux機器上跟蹤系統事件的守護進程名是什麼？### <a class="header-anchor" href="#_3-在你的linux機器上跟蹤系統事件的守護進程名是什麼" aria-label="Permalink to “3. 在你的Linux機器上跟蹤系統事件的守護進程名是什麼？###”">​</a></h3><p><strong>答案</strong>：&#39;syslogd&#39;，它負責跟蹤系統信息，並將跟蹤日誌存儲在特定的日誌文件裏。</p><h3 id="_4-在-root分區運行-fsck-命令的最低要求是什麼" tabindex="-1">4. 在/root分區運行&#39;fsck&#39;命令的最低要求是什麼？### <a class="header-anchor" href="#_4-在-root分區運行-fsck-命令的最低要求是什麼" aria-label="Permalink to “4. 在/root分區運行&#39;fsck&#39;命令的最低要求是什麼？###”">​</a></h3><p><strong>答案</strong>：/root分區必須掛載為只讀模式，而不是讀寫模式</p><h3 id="_5-如何分層複製-home目錄到另一個目錄" tabindex="-1">5. 如何分層複製/home目錄到另一個目錄？### <a class="header-anchor" href="#_5-如何分層複製-home目錄到另一個目錄" aria-label="Permalink to “5. 如何分層複製/home目錄到另一個目錄？###”">​</a></h3><p><strong>答案</strong>：Linux的&#39;cpio&#39;命令起到了效果。&#39;cpio&#39;可以分層地複製文件和目錄層次結構到另一個位置。</p><h3 id="_6-在linux中-怎樣實現日誌文件的自動替換" tabindex="-1">6. 在Linux中，怎樣實現日誌文件的自動替換？### <a class="header-anchor" href="#_6-在linux中-怎樣實現日誌文件的自動替換" aria-label="Permalink to “6. 在Linux中，怎樣實現日誌文件的自動替換？###”">​</a></h3><p><strong>答案</strong>：&#39;logrotate&#39;提供日誌自動替換功能。</p><h3 id="_7-怎樣知道linux中是誰在安排工作" tabindex="-1">7. 怎樣知道Linux中是誰在安排工作？### <a class="header-anchor" href="#_7-怎樣知道linux中是誰在安排工作" aria-label="Permalink to “7. 怎樣知道Linux中是誰在安排工作？###”">​</a></h3><p><strong>答案</strong>：使用&#39;at&#39;命令加上&#39;-l&#39;選項，就可以查出。</p><h3 id="_8-如何在不解壓tar包的前提下-查看包裏的內容" tabindex="-1">8. 如何在不解壓tar包的前提下，查看包裏的內容？ <a class="header-anchor" href="#_8-如何在不解壓tar包的前提下-查看包裏的內容" aria-label="Permalink to “8. 如何在不解壓tar包的前提下，查看包裏的內容？”">​</a></h3><p><strong>答案</strong>：使用&#39;tar -tvf&#39;。選項‘t’(顯示內容)，‘v’（詳細報告tar處理的文件信息），‘f’（使用檔案文件或者設備）</p><h3 id="_9-什麼是頁面錯誤-它是怎麼發生的" tabindex="-1">9. 什麼是頁面錯誤，它是怎麼發生的？### <a class="header-anchor" href="#_9-什麼是頁面錯誤-它是怎麼發生的" aria-label="Permalink to “9. 什麼是頁面錯誤，它是怎麼發生的？###”">​</a></h3><p><strong>答案</strong>：當一個程序請求內存中不存在的數據時，就會產生頁面錯誤，導致的結果就是程序停止。</p><h3 id="_10-什麼是在程序中返回代碼" tabindex="-1">10. 什麼是在程序中返回代碼？### <a class="header-anchor" href="#_10-什麼是在程序中返回代碼" aria-label="Permalink to “10. 什麼是在程序中返回代碼？###”">​</a></h3><p><strong>答案</strong>：返回代碼是shell的特性。返回代碼顯示了程序的狀態，一個成功的程序執行後返回‘0’，&amp;&amp;可以用來決定那個應用程序先執行。</p><p>好了，文章要結束了。不久以後，我還會在這分享其餘有趣文章的，記得和我們保持聯繫。還有，別忘了在評論欄裏面向我們提供您的寶貴意見。</p><hr>`,29)),o("p",null,[n[1]||(n[1]=a("via: ",-1)),e(t,{href:"http://www.tecmint.com/10-useful-interview-questions-and-answers-on-linux-commands/"},{default:r(()=>[...n[0]||(n[0]=[a("http://www.tecmint.com/10-useful-interview-questions-and-answers-on-linux-commands/",-1)])]),_:1})]),o("p",null,[n[3]||(n[3]=a("原文作者：",-1)),e(t,{href:"http://www.tecmint.com/author/avishek/"},{default:r(()=>[...n[2]||(n[2]=[a("Avishek Kumar",-1)])]),_:1})]),o("p",null,[n[6]||(n[6]=a("譯者：",-1)),e(t,{href:"https://github.com/su-kaiyao"},{default:r(()=>[...n[4]||(n[4]=[a("su-kaiyao",-1)])]),_:1}),n[7]||(n[7]=a(" 校對：",-1)),e(t,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...n[5]||(n[5]=[a("Caroline",-1)])]),_:1})]),o("p",null,[n[10]||(n[10]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...n[8]||(n[8]=[a("LCTT",-1)])]),_:1}),n[11]||(n[11]=a(" 原創翻譯，",-1)),e(t,{href:"http://linux.cn/"},{default:r(()=>[...n[9]||(n[9]=[a("Linux中國",-1)])]),_:1}),n[12]||(n[12]=a(" 榮譽推出",-1))])])}const C=s(p,[["render",m]]);export{b as __pageData,C as default};
